\label{rem-delta0-digraph}

Let \(\boldsymbol{x}=\sum_i\operatorname{shift}^{d_i}(\boldsymbol{s}_i)\) with every \(\boldsymbol{s}_i\in S_n\). Then the unique lex submodule
\(L\) with \(\operatorname{HF}(F/L)=\boldsymbol{x}\) is proper.
\label{lem-lexproper}

Fix \(n\ge1\), \(r\ge1\) and a sorted \(\boldsymbol{d}\). Let \(A'_n\) be \(A_n\) with the columns \(\rho=0\) and
\(\rho=1\) set to zero, \(\boldsymbol{u}'_n\) its row sums, and \(T'_n(\delta)\) built from \(A'_n\) as in
Definition \ref{def-uT}. Then
\begin{equation}\label{eq:auto-16}
  \lvert\mathrm{FF}_{\mathrm{pr}}(n;\boldsymbol{d})\rvert
  \;=\;\lvert\mathrm{CT}_{\mathrm{pr}}(n;\boldsymbol{d})\rvert
  \;=\;\boldsymbol{u}'_n\cdot T'_n(\delta_2)\cdots T'_n(\delta_r)\cdot\boldsymbol{1}_n .
\end{equation}
\label{thm-proper}

For \(n\ge1\), \(|\mathrm{FF}_{\mathrm{pr}}(n;\boldsymbol{d})|=|S_n|^{\,r}\) if and only if every gap satisfies
\(\delta_i\ge n-1\).
\label{prop-proper-threshold}

Two sequences recorded in earlier work on this project are reproduced exactly by
Theorem \ref{thm-proper} and extended. For \(r=2\), \(n=2,\dots,9\):
\begin{equation}\label{eq:auto-17}
  \delta=0:\quad 3,\ 12,\ 69,\ 627,\ 9904,\ 296289,\ 18009389,\ 2346218172,
\end{equation}
\begin{equation}\label{eq:auto-18}
  \delta=1:\quad 4,\ 22,\ 162,\ 1858,\ 38232,\ 1571774,\ 138881518,\ 27635025278 .
\end{equation}
The prefixes through \(n=6\) are the independently enumerated ones. Neither sequence, nor \(|S_n|\)
itself, appears to be in the OEIS (searched October 2026).
\label{rem-proper-sequences}

(\emph{The support of the transfer matrix.}) Let \(n\ge1\) and \(\delta\ge0\). For all \(\tau,\tau'\) in
the range \eqref{eq:def-uT-range},
\begin{equation}\label{eq:transfer-support}
  T_n(\delta)[\tau][\tau']>0\quad\Longleftrightarrow\quad\tau'\ge\tau-\delta .
\end{equation}
In \(T'_n(\delta)\) the two columns \(\tau'=-1\) and \(\tau'=0\) vanish identically, and
\eqref{eq:transfer-support} holds as stated for every \(\tau'\in\lbrace1,\dots,n\rbrace\).
\label{lem-transfer-support}

For a constant gap \(\delta\), put
\begin{equation}\label{eq:def-ar}
  a_r\;:=\;\lvert\mathrm{FF}(n;0,\delta,2\delta,\dots,(r-1)\delta)\rvert
  \;=\;\boldsymbol{u}_n\cdot T_n(\delta)^{r-1}\cdot\boldsymbol{1}_n .
\end{equation}
Then \(a_r\) satisfies the linear recurrence whose characteristic polynomial is
that of \(T_n(\delta)\), and its exponential growth rate is the Perron root \(\lambda\) of
\(T_n(\delta)\), in the sense that \(a_r^{1/r}\to\lambda\). The same holds for the proper count with
\(T'_n(\delta)\).
\label{prop-recurrence}

(\emph{The constant, for a positive gap.}) Fix \(n\ge1\) and a constant gap \(\delta\ge1\), let \(a_r\) be
as in \eqref{eq:def-ar}, and let \(\lambda\) be the Perron root of \(T_n(\delta)\). Then there are
constants \(K>0\) and \(\varrho\) with \(0\le\varrho<\lambda\) such that
\begin{equation}\label{eq:growth-constant}
  a_r\;=\;K\lambda^{\,r}+O(\varrho^{\,r})\qquad(r\to\infty) ,
\end{equation}
and in particular \(a_r\sim K\lambda^{\,r}\). The same holds for the proper count, with
\(T'_n(\delta)\), its own Perron root and its own constants.
\label{prop-growth-constant}

(\emph{Normal form: all the gap-dependence sits in one shift.}) Two matrices are needed, and only two. The
\textbf{base matrix} is the transfer matrix at gap zero,
\begin{equation}\label{eq:def-B}
  B_n\;=\;T_n(0),\qquad B_n[\tau][\tau']=\sum_{\rho>\tau}A_n[\tau'][\rho] ,
\end{equation}
which by Proposition \ref{prop-delta0} is unipotent and carries the Pascal superdiagonal of
Lemma \ref{lem-A-structure}. The \textbf{saturating one-step shift} on the \(\operatorname{top}\)-index is the
\((n+2)\times(n+2)\) matrix
\begin{equation}\label{eq:def-P}
  P_n[\tau][\tau']=\begin{cases}
    1, & \tau'=\max(\tau-1,-1),\\
    0, & \text{otherwise},
  \end{cases}
  \qquad \tau,\tau'\in\lbrace-1,0,\dots,n\rbrace .
\end{equation}
Both are indexed as in Definition \ref{def-uT}. Let \(e_{-1}\) be the standard basis vector supported at
the index \(-1\). Then for every \(\delta\ge0\),
\begin{align}
  T_n(\delta) &= P_n^{\delta}B_n ,\label{eq:normalform}\\
  \boldsymbol{u}_n    &= e_{-1}^{\!\top}B_n ,\label{eq:normalform-u}
\end{align}
and consequently
\begin{equation}\label{eq:normalform-product}
  \lvert\mathrm{FF}(n;\boldsymbol{d})\rvert
   =e_{-1}^{\!\top}B_n\,P_n^{\delta_2}B_n\,P_n^{\delta_3}\cdots P_n^{\delta_r}B_n\,\boldsymbol{1}_n .
\end{equation}
\label{prop-normalform}

(\emph{The Perron root above the threshold.}) Let \(\lambda(\delta)\) be the Perron root of \(T_n(\delta)\)
and \(\lambda_{\mathrm{pr}}(\delta)\) that of its proper analogue. Then
\begin{align}
  \lambda(\delta) &= \lvert\mathcal F_n\rvert \quad\text{for every }\delta\ge n+1,\label{eq:perron-threshold}\\
  \lambda_{\mathrm{pr}}(\delta) &= \lvert S_n\rvert \quad\text{for every }\delta\ge n-1 .\label{eq:perron-threshold-pr}
\end{align}
In both cases the value is attained, not merely approached, and the thresholds are exactly those of
Propositions \ref{prop-threshold} and \ref{prop-proper-threshold}.
\label{prop-perron-threshold}

Fix \(n\ge1\) and \(r\ge1\); let \(d_1\le\cdots\le d_r\) be integers and put
\(\delta_i=d_i-d_{i-1}\) for \(2\le i\le r\), so that \(\boldsymbol{d}\) is sorted and the gaps are
non-negative. Let \(p\ge n\), let \(\mathcal F_n^{(p)}\) be as in Definition \ref{def-twoparam}, and set
\begin{equation}\label{eq:Ap}
  A^{(p)}_n[\tau][\rho]=E^p(\tau,\rho-1)-E^p(\tau-1,\rho-1),
  \qquad \tau=-1,\dots,n,\quad\rho=0,\dots,n+1,
\end{equation}
with \(\boldsymbol{u}^{(p)}_n\) its vector of row sums and \(T^{(p)}_n(\delta)\) built from \(A^{(p)}_n\) by
\eqref{eq:def-u}--\eqref{eq:def-T}, both indexed as in Definition \ref{def-uT}. Then
\begin{equation}\label{eq:auto-20}
  \lvert\mathrm{FF}^{(p)}(n;\boldsymbol{d})\rvert\;=\;\boldsymbol{u}^{(p)}_n\cdot T^{(p)}_n(\delta_2)\cdots T^{(p)}_n(\delta_r)\cdot\boldsymbol{1}_n ,
\end{equation}
and for fixed \(n\), \(r\) and \(\boldsymbol{d}\) this is a polynomial in \(p\).
\label{thm-poly-p}

(\emph{Degree and leading coefficient in \(p\).}) Fix \(n\ge1\), \(r\ge1\) and a sorted \(\boldsymbol{d}\) with
gaps \(\delta_i=d_i-d_{i-1}\). Then
\begin{equation}\label{eq:degree-in-p}
  \deg_p\lvert\mathrm{FF}^{(p)}(n;\boldsymbol{d})\rvert
   \;=\; r\binom{n+1}{2}\;-\;\sum_{i=2}^{r}\binom{\kappa_i+1}{2},
\end{equation}
which is strictly increasing in each \(\delta_i\) up to \(\delta_i=n\) and constant thereafter. If
moreover every gap satisfies \(\delta_i\ge1\), then the summands decouple to leading order:
\begin{equation}\label{eq:lc-in-p}
  \lvert\mathrm{FF}^{(p)}(n;\boldsymbol{d})\rvert\;\sim\;F^p(n)\prod_{i=2}^{r}E^p(n,\kappa_i)
  \qquad(p\to\infty).
\end{equation}
\label{thm-asymptotics-p}

(\emph{The proper analogue.}) Let \(A'^{(p)}_n\) be the matrix \(A^{(p)}_n\) with its columns \(\rho=0\)
and \(\rho=1\) set to zero, let \(\boldsymbol{u}'^{(p)}_n\) be the vector of its row sums, and let
\(T'^{(p)}_n(\delta)\) be built from \(A'^{(p)}_n\) by \eqref{eq:def-u}--\eqref{eq:def-T}. Then, for every
\(p\ge n\),
\begin{equation}\label{eq:proper-p-product}
  \lvert\mathrm{FF}^{(p)}_{\mathrm{pr}}(n;\boldsymbol{d})\rvert
  \;=\;\boldsymbol{u}'^{(p)}_n\cdot T'^{(p)}_n(\delta_2)\cdots T'^{(p)}_n(\delta_r)\cdot\boldsymbol{1}_n ,
\end{equation}
and this count is a polynomial in \(p\), whose degree is
\begin{equation}\label{eq:proper-degree-in-p}
  \deg_p\lvert\mathrm{FF}^{(p)}_{\mathrm{pr}}(n;\boldsymbol{d})\rvert
   \;=\; r\binom{n+1}{2}\;-\;1\;-\;\sum_{i=2}^{r}\binom{\kappa_i'+1}{2},
\end{equation}
The degree is strictly increasing in each \(\delta_i\) up to \(\delta_i=n-1\), and it is constant
thereafter. If moreover every gap satisfies \(\delta_i\ge1\), then
\begin{equation}\label{eq:proper-lc-in-p}
  \lvert\mathrm{FF}^{(p)}_{\mathrm{pr}}(n;\boldsymbol{d})\rvert\;\sim\;E^p(n,1)\prod_{i=2}^{r}E^p(n,\kappa_i')
  \qquad(p\to\infty),
\end{equation}
where \(E^p(n,1)\) may be replaced by \(\lvert S_n^{(p)}\rvert\), of which it is the dominant term.
\label{thm-asymptotics-p-proper}
